import type { EvnApiResponse, ScheduleItem } from '../types';

/**
 * Parses an HTML response from the EVN website to extract power outage schedule data.
 */
const parseHtmlResponse = (html: string, teamCode: string): ScheduleItem[] => {
    try {
        const parser = new DOMParser();
        const doc = parser.parseFromString(html, 'text/html');
        const entries = doc.querySelectorAll('.entry');
        const scheduleItems: ScheduleItem[] = [];

        if (entries.length === 0) return [];

        entries.forEach((entry, index) => {
            const areaElement = entry.querySelector('.where');
            const timeElement = entry.querySelector('.time > span');
            const reasonElement = entry.querySelector('.cause > span');

            if (areaElement && timeElement && reasonElement) {
                const khuVucRaw = areaElement.textContent || '';
                const thoiGianRaw = timeElement.textContent || '';
                const lyDoRaw = reasonElement.textContent || '';

                const tenKhuVuc = khuVucRaw.replace('KHU VỰC:', '').trim();
                const lyDo = lyDoRaw.trim();

                const timeParts = thoiGianRaw.trim().split('đến');
                if (timeParts.length === 2) {
                    const [startStr, endStr] = timeParts;
                    const timeRegex = /(\d{2}:\d{2}:\d{2})\s+ngày\s+(\d{2}\/\d{2}\/\d{4})/;
                    const startTimeMatch = startStr.match(timeRegex);
                    const endTimeMatch = endStr.match(timeRegex);

                    if (startTimeMatch && endTimeMatch) {
                        const thoiGianNgung = `${startTimeMatch[1]} ${startTimeMatch[2]}`;
                        const thoiGianCoDienLai = `${endTimeMatch[1]} ${endTimeMatch[2]}`;

                        scheduleItems.push({
                            ID: `${teamCode}-${Date.now()}-${index}`,
                            MA_DVIQLY: teamCode,
                            TEN_DVIQLY: '',
                            TEN_KHU_VUC: tenKhuVuc,
                            THOI_GIAN_NGUNG: thoiGianNgung,
                            THOI_GIAN_CO_DIEN_LAI: thoiGianCoDienLai,
                            LY_DO: lyDo,
                        });
                    }
                }
            }
        });

        return scheduleItems;
    } catch (parseError) {
        console.error("Lỗi khi phân tích phản hồi HTML:", parseError);
        throw new Error("Không thể phân tích dữ liệu HTML nhận được từ máy chủ.");
    }
};

/**
 * Helper to fetch data with a timeout.
 */
const fetchWithTimeout = async (url: string, options: RequestInit = {}, timeout = 10000) => {
  const controller = new AbortController();
  const id = setTimeout(() => controller.abort(), timeout);
  try {
    const response = await fetch(url, { ...options, signal: controller.signal });
    clearTimeout(id);
    return response;
  } catch (error) {
    clearTimeout(id);
    throw error;
  }
};

/**
 * Attempts to fetch from EVN using various proxy options in sequence.
 */
export const fetchSchedule = async (teamCode: string, date: string): Promise<ScheduleItem[]> => {
  const [year, month, day] = date.split('-');
  const formattedDate = `${day}/${month}/${year}`;
  const targetUrl = `https://www.cskh.evnspc.vn/TraCuu/GetThongTinLichNgungGiamCungCapDien?madvi=${teamCode}&ngay=${formattedDate}&ChucNang=MaDonVi`;

  // Define proxy strategies
  const proxyStrategies = [
    {
      name: "AllOrigins",
      url: `https://api.allorigins.win/get?url=${encodeURIComponent(targetUrl)}&timestamp=${Date.now()}`,
      parser: async (res: Response) => {
        const json = await res.json();
        return json.contents || "";
      }
    },
    {
      name: "Codetabs",
      url: `https://api.codetabs.com/v1/proxy?url=${encodeURIComponent(targetUrl)}`,
      parser: async (res: Response) => res.text()
    },
    {
      name: "CorsProxy.io",
      url: `https://corsproxy.io/?${encodeURIComponent(targetUrl)}`,
      parser: async (res: Response) => res.text()
    }
  ];

  let responseText = "";
  let errors: string[] = [];

  // Iterate through strategies until one succeeds
  for (const strategy of proxyStrategies) {
    try {
      const response = await fetchWithTimeout(strategy.url);
      if (response.ok) {
        responseText = await strategy.parser(response);
        if (responseText && responseText.trim().length > 0) {
          // Success! Break out of loop.
          break;
        }
      } else {
        errors.push(`${strategy.name}: HTTP ${response.status}`);
      }
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      errors.push(`${strategy.name}: ${msg}`);
      console.warn(`Proxy ${strategy.name} failed for ${teamCode}:`, msg);
    }
  }

  if (!responseText || responseText.trim() === "") {
    const detailedError = errors.join(", ");
    throw new Error(`Tất cả các cổng trung gian (proxy) đều thất bại. Chi tiết: ${detailedError}. Vui lòng thử lại sau vài phút.`);
  }

  // Parse the successful response text
  try {
      // Try parsing as JSON first (Official API behavior)
      const result: EvnApiResponse = JSON.parse(responseText);
      if (result.success) {
        return result.data || [];
      }
      throw new Error(result.message || 'Lỗi không xác định từ API EVN.');
  } catch (jsonError) {
      // Fallback to HTML parsing if not JSON (sometimes EVN returns HTML even on API endpoints when errors occur)
      const trimmed = responseText.trim();
      if (trimmed.startsWith('<') || trimmed.toLowerCase().includes('<!doctype html>')) {
          return parseHtmlResponse(responseText, teamCode);
      }

      // If we got here, it's not JSON and not recognizable HTML
      console.error("Malformed response from proxy:", responseText.substring(0, 200));
      throw new Error('Định dạng phản hồi từ máy chủ EVN không hợp lệ. Vui lòng thử lại sau.');
  }
};

/**
 * Converts a Date object to a string in "yyyy-MM-dd" format.
 * @param date The date to format.
 * @returns The formatted date string.
 */
export const toYyyyMmDd = (date: Date): string => {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
};

/**
 * Calculates start and end date strings based on a preset filter.
 * @param filter The date filter preset ('today', 'tomorrow', 'this_week', 'this_month').
 * @returns An object containing the startDate and endDate strings.
 */
export const getDatePresetsForFilter = (filter: 'today' | 'tomorrow' | 'this_week' | 'this_month'): { startDate: string; endDate: string } => {
  const todayDateObj = new Date();
  todayDateObj.setHours(0, 0, 0, 0); // Use for comparison to ignore time

  let startDate: Date;
  let endDate: Date;

  switch (filter) {
    case 'today':
      startDate = new Date(todayDateObj);
      endDate = new Date(todayDateObj);
      break;
    case 'tomorrow':
      startDate = new Date(todayDateObj);
      startDate.setDate(startDate.getDate() + 1);
      endDate = new Date(startDate);
      break;
    case 'this_week': {
      // Monday of the current week
      const dayOfWeek = todayDateObj.getDay(); // 0=Sun, 1=Mon
      const diffToMonday = dayOfWeek === 0 ? -6 : 1 - dayOfWeek;
      const mondayOfWeek = new Date(todayDateObj);
      mondayOfWeek.setDate(todayDateObj.getDate() + diffToMonday);

      // If Monday is in the past, start the week from today
      startDate = mondayOfWeek < todayDateObj ? new Date(todayDateObj) : mondayOfWeek;

      // Sunday of the current week
      endDate = new Date(mondayOfWeek);
      endDate.setDate(mondayOfWeek.getDate() + 6);
      break;
    }
    case 'this_month': {
      // First day of the current month
      const firstDayOfMonth = new Date(todayDateObj.getFullYear(), todayDateObj.getMonth(), 1);

      // If the 1st of the month is in the past, start from today
      startDate = firstDayOfMonth < todayDateObj ? new Date(todayDateObj) : firstDayOfMonth;

      // Last day of the current month
      endDate = new Date(todayDateObj.getFullYear(), todayDateObj.getMonth() + 1, 0);
      break;
    }
  }

  return {
    startDate: toYyyyMmDd(startDate),
    endDate: toYyyyMmDd(endDate),
  };
};

/**
 * Generates an array of date strings ("yyyy-MM-dd") between a start and end date.
 * @param startDateStr The start date in "yyyy-MM-dd" format.
 * @param endDateStr The end date in "yyyy-MM-dd" format.
 * @returns An array of date strings.
 */
export const getDatesInRange = (startDateStr: string, endDateStr: string): string[] => {
  const dates: string[] = [];
  let currentDate = new Date(`${startDateStr}T00:00:00`);
  const endDate = new Date(`${endDateStr}T00:00:00`);

  while (currentDate <= endDate) {
    dates.push(currentDate.toISOString().split('T')[0]);
    currentDate.setDate(currentDate.getDate() + 1);
  }
  return dates;
};

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { POWER_COMPANIES } from './constants';
import { fetchSchedule } from './services/evnService';
import { generateScheduleImage, summarizeDailySchedule } from './services/geminiService';
import { getDatePresetsForFilter, getDatesInRange, toYyyyMmDd } from './utils/dateUtils';
import Loader from './components/Loader';
import ScheduleDisplay from './components/ScheduleDisplay';
import ImageDisplay from './components/ImageDisplay';
import ThemeSwitcher from './components/ThemeSwitcher';
import type { ScheduleItem, PowerTeam } from './types';

function App() {
  const todayString = useMemo(() => {
    const d = new Date();
    const year = d.getFullYear();
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  }, []);

  const [selectedCompany, setSelectedCompany] = useState<string>('');
  const [selectedTeam, setSelectedTeam] = useState<string>('');
  const [selectedStartDate, setSelectedStartDate] = useState<string>(todayString);
  const [selectedEndDate, setSelectedEndDate] = useState<string>(todayString);
  const [scheduleData, setScheduleData] = useState<ScheduleItem[] | null>(null);
  const [areaFilter, setAreaFilter] = useState<string>('');
  const [generatedImageUrl, setGeneratedImageUrl] = useState<string | null>(null);
  const [isFetching, setIsFetching] = useState<boolean>(false);
  const [fetchProgress, setFetchProgress] = useState<string>('');
  const [isGenerating, setIsGenerating] = useState<boolean>(false);
  const [isSummarizing, setIsSummarizing] = useState<boolean>(false);
  const [showSummaries, setShowSummaries] = useState<boolean>(false);
  const [isScheduleFetched, setIsScheduleFetched] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [dailySummaries, setDailySummaries] = useState<Record<string, string>>({});
  const summaryGenerationId = useRef(0);

  const [apiKeyError, setApiKeyError] = useState<string | null>(() => {
    if (!process.env.API_KEY) {
      return "API Key của Gemini bị thiếu. Các tính năng tóm tắt và tạo ảnh sẽ bị vô hiệu hóa. Vui lòng cấu hình biến môi trường API_KEY.";
    }
    return null;
  });

  const [theme, setTheme] = useState<'light' | 'dark'>(() => {
    const savedTheme = localStorage.getItem('theme');
    if (savedTheme === 'light' || savedTheme === 'dark') {
      return savedTheme;
    }
    return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
  });

  useEffect(() => {
    const root = window.document.documentElement;
    if (theme === 'dark') {
      root.classList.add('dark');
    } else {
      root.classList.remove('dark');
    }
    localStorage.setItem('theme', theme);
  }, [theme]);

  const selectedTeamName = useMemo(() => {
    if (!selectedCompany) return '';
    if (selectedTeam === '') {
        return POWER_COMPANIES[selectedCompany]?.name;
    }
    return POWER_COMPANIES[selectedCompany]?.teams[selectedTeam];
  }, [selectedCompany, selectedTeam]);

  const generateAndSetSummaries = async (schedule: ScheduleItem[], teamName: string) => {
    if (!schedule || schedule.length === 0) {
      setDailySummaries({});
      return;
    }

    const currentGenerationId = ++summaryGenerationId.current;
    setIsSummarizing(true);
    setDailySummaries({});

    try {
      const schedulesByDate = schedule.reduce((acc, item) => {
        try {
          const datePart = item.THOI_GIAN_NGUNG.split(' ')[1];
          if (datePart) {
            if (!acc[datePart]) {
              acc[datePart] = [];
            }
            acc[datePart].push(item);
          }
        } catch (e) {}
        return acc;
      }, {} as Record<string, ScheduleItem[]>);

      const newSummaries: Record<string, string> = {};
      for (const [date, items] of Object.entries(schedulesByDate)) {
        if (summaryGenerationId.current !== currentGenerationId) return;
        try {
          const summary = await summarizeDailySchedule(items, teamName);
          if (summary) newSummaries[date] = summary;
          // Standard Gemini Free Tier has rate limits, 4s delay is safer
          await new Promise(resolve => setTimeout(resolve, 4100));
        } catch (error) {
          const errorMessage = error instanceof Error ? error.message : String(error);
          newSummaries[date] = `Lỗi: ${errorMessage}`;
          if (errorMessage.toLowerCase().includes('api key not valid')) {
              setApiKeyError('API Key của Gemini không hợp lệ.');
          }
        }
      }
      if (summaryGenerationId.current === currentGenerationId) setDailySummaries(newSummaries);
    } finally {
        if (summaryGenerationId.current === currentGenerationId) setIsSummarizing(false);
    }
  };

  const availableTeams: PowerTeam = useMemo(() => {
    if (!selectedCompany || !POWER_COMPANIES[selectedCompany]) return {};
    return POWER_COMPANIES[selectedCompany].teams;
  }, [selectedCompany]);

  const resetState = () => {
    setScheduleData(null);
    setGeneratedImageUrl(null);
    setIsScheduleFetched(false);
    setError(null);
    setAreaFilter('');
    setDailySummaries({});
    setIsSummarizing(false);
    setShowSummaries(false);
    setFetchProgress('');
    summaryGenerationId.current += 1;
  };

  const handleCompanyChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    setSelectedCompany(e.target.value);
    setSelectedTeam('');
    resetState();
  };

  const handleTeamChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    setSelectedTeam(e.target.value);
    resetState();
  };

  const handleStartDateChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSelectedStartDate(e.target.value);
    resetState();
  };

  const handleEndDateChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSelectedEndDate(e.target.value);
    resetState();
  };

  const handleDateFilterClick = (filter: 'today' | 'tomorrow' | 'this_week' | 'this_month') => {
    const { startDate, endDate } = getDatePresetsForFilter(filter);
    setSelectedStartDate(startDate);
    setSelectedEndDate(endDate);
    resetState();
  };

  const handleStepDay = (step: number) => {
    const currentStart = new Date(`${selectedStartDate}T00:00:00`);
    const currentEnd = new Date(`${selectedEndDate}T00:00:00`);

    currentStart.setDate(currentStart.getDate() + step);
    currentEnd.setDate(currentEnd.getDate() + step);

    const newStart = toYyyyMmDd(currentStart);
    const newEnd = toYyyyMmDd(currentEnd);

    setSelectedStartDate(newStart);
    setSelectedEndDate(newEnd);
    resetState();
  };

  const handleToggleSummaries = () => {
    if (!showSummaries) {
      if (apiKeyError) {
          setError("Không thể tạo tóm tắt: API Key bị thiếu hoặc không hợp lệ.");
          setShowSummaries(true);
          return;
      }
      const shouldGenerate = scheduleData && scheduleData.length > 0 && Object.keys(dailySummaries).length === 0;
      if (shouldGenerate) generateAndSetSummaries(scheduleData, selectedTeamName);
    }
    setShowSummaries(prev => !prev);
  };

  const filteredScheduleData = useMemo(() => {
    if (!scheduleData) return null;
    const startFilterDate = new Date(selectedStartDate);
    startFilterDate.setHours(0, 0, 0, 0);
    const endFilterDate = new Date(selectedEndDate);
    endFilterDate.setHours(0, 0, 0, 0);
    const filterText = areaFilter.trim().toLowerCase();

    return scheduleData.filter(item => {
      try {
        const datePart = item.THOI_GIAN_NGUNG.split(' ')[1];
        if (!datePart) return false;
        const [day, month, year] = datePart.split('/');
        const scheduleDate = new Date(parseInt(year), parseInt(month) - 1, parseInt(day));
        scheduleDate.setHours(0, 0, 0, 0);
        if (scheduleDate < startFilterDate || scheduleDate > endFilterDate) return false;
      } catch (e) { return false; }
      if (filterText) return item.TEN_KHU_VUC.toLowerCase().includes(filterText);
      return true;
    });
  }, [scheduleData, areaFilter, selectedStartDate, selectedEndDate]);

  const handleFetch = async () => {
    if (!selectedCompany || !selectedStartDate || !selectedEndDate) {
      setError('Vui lòng chọn công ty điện lực và khoảng ngày tra cứu.');
      return;
    }
    if (selectedStartDate < todayString) {
        setError('Vui lòng chọn ngày bắt đầu từ hôm nay trở đi.');
        return;
    }
    if (new Date(selectedStartDate) > new Date(selectedEndDate)) {
      setError('Ngày bắt đầu không được lớn hơn ngày kết thúc.');
      return;
    }

    resetState();
    setIsFetching(true);
    setFetchProgress('Bắt đầu tải dữ liệu...');

    const datesToFetch = getDatesInRange(selectedStartDate, selectedEndDate);
    const isFetchingAllTeams = selectedTeam === '';
    const teamCodesToFetch = isFetchingAllTeams ? Object.keys(availableTeams) : [selectedTeam];

    if (isFetchingAllTeams && teamCodesToFetch.length === 0) {
      setError(`Công ty này chưa có danh sách đội chi tiết.`);
      setIsFetching(false);
      return;
    }

    const successfulData: ScheduleItem[] = [];
    const failedDetails: string[] = [];
    const totalRequests = teamCodesToFetch.length * datesToFetch.length;
    let completedRequests = 0;

    try {
      // Process teams sequentially with a slightly larger delay to avoid proxy rate-limiting
      for (const teamCode of teamCodesToFetch) {
        for (const date of datesToFetch) {
          try {
            completedRequests++;
            const teamNameDisplay = availableTeams[teamCode] || "Đội đang tải";
            setFetchProgress(`Đang tải (${completedRequests}/${totalRequests}): ${teamNameDisplay} ngày ${date}...`);

            const schedules = await fetchSchedule(teamCode, date);
            const augmented = schedules.map(item => ({
              ...item,
              TEN_DVIQLY: item.TEN_DVIQLY || teamNameDisplay,
            }));
            successfulData.push(...augmented);

            // Wait 300ms between requests to be gentle
            await new Promise(r => setTimeout(r, 300));
          } catch (err) {
            // Ensure err is treated as a string
            const errorMsg = err instanceof Error ? err.message : String(err);
            const teamNameDisplay = availableTeams[teamCode] || teamCode;
            failedDetails.push(`${teamNameDisplay} (${date}): ${errorMsg}`);
          }
        }
      }

      if (successfulData.length === 0 && failedDetails.length > 0) {
        setError(`Tất cả yêu cầu đều thất bại:\n\n${failedDetails.slice(0, 10).join('\n')}${failedDetails.length > 10 ? '\n...và ' + (failedDetails.length - 10) + ' lỗi khác.' : ''}`);
      } else if (failedDetails.length > 0) {
        console.warn("Một số yêu cầu tra cứu thất bại:", failedDetails);
        // Notice if partial success
        setFetchProgress(`Đã tải xong ${successfulData.length} mục (có ${failedDetails.length} lỗi).`);
      } else {
        setFetchProgress(`Tải xong ${successfulData.length} mục dữ liệu.`);
      }

      successfulData.sort((a, b) => {
        const parse = (s: string) => {
          try {
            const [t, d] = s.split(' ');
            const [dd, mm, yy] = d.split('/');
            return new Date(`${yy}-${mm}-${dd}T${t}`).getTime();
          } catch(e) { return 0; }
        };
        return parse(a.THOI_GIAN_NGUNG) - parse(b.THOI_GIAN_NGUNG);
      });

      setScheduleData(successfulData);
      if (successfulData.length > 0) setIsScheduleFetched(true);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Lỗi không xác định.');
    } finally {
      setIsFetching(false);
    }
  };

  const handleGenerateImage = async () => {
    if (!filteredScheduleData || filteredScheduleData.length === 0) {
      setError('Không có dữ liệu lịch để tạo ảnh.');
      return;
    }
    setError(null);
    setGeneratedImageUrl(null);
    setIsGenerating(true);
    try {
      const imageUrl = await generateScheduleImage(filteredScheduleData, selectedTeamName);
      setGeneratedImageUrl(imageUrl);
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : String(err);
      setError(errorMessage);
      if (errorMessage.toLowerCase().includes('api key not valid')) setApiKeyError('API Key không hợp lệ.');
    } finally { setIsGenerating(false); }
  };

  const isLoading = isFetching || isGenerating;
  let loadingMessage = isFetching ? fetchProgress : (isGenerating ? 'Đang tạo ảnh với Gemini...' : '');

  const backgroundClass = useMemo(() => {
    if (generatedImageUrl) return 'bg-gradient-to-br from-teal-50 to-green-100 dark:from-slate-900 dark:to-teal-950';
    if (isScheduleFetched) return 'bg-gradient-to-br from-blue-50 to-indigo-100 dark:from-slate-900 dark:to-blue-950';
    return 'bg-gradient-to-br from-gray-50 to-slate-100 dark:from-gray-900 dark:to-slate-950';
  }, [isScheduleFetched, generatedImageUrl]);

  return (
    <div className={`min-h-screen ${backgroundClass} text-gray-900 dark:text-gray-100 font-sans transition-colors duration-500`}>
      <main className="container mx-auto p-4 md:p-8">
        <div className="relative max-w-7xl mx-auto bg-white dark:bg-gray-800/50 backdrop-blur-sm rounded-2xl shadow-2xl p-6 md:p-8 border border-gray-200 dark:border-gray-700">
          <div className="absolute top-4 right-4 z-10">
            <ThemeSwitcher theme={theme} setTheme={setTheme} />
          </div>
          <div className="text-center mb-8">
            <h1 className="text-3xl md:text-4xl font-extrabold text-transparent bg-clip-text bg-gradient-to-r from-blue-500 to-teal-400">
              Tạo Ảnh Lịch Cúp Điện
            </h1>
            <p className="mt-2 text-gray-600 dark:text-gray-300">
              Tra cứu lịch từ EVN và tạo ảnh thông báo chuyên nghiệp.
            </p>
          </div>

          <div className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
              <div>
                <label className="block text-sm font-medium mb-1">Công ty Điện lực</label>
                <select value={selectedCompany} onChange={handleCompanyChange} className="w-full p-3 bg-white dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-lg">
                  <option value="">-- Chọn công ty --</option>
                  {Object.entries(POWER_COMPANIES).map(([code, company]) => (
                    <option key={code} value={code}>{company.name}</option>
                  ))}
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">Đội Điện lực</label>
